        JISREM.CLEANUP_CASE_QUEUE
    SET
        status = 'VALIDATION_FAILED',
        message = v_validation_error
    WHERE
        cleanup_id = '6f79fa9b-dfb8-4d49-a8e3-28124fb629a4'
        AND charge_id = 1108406;
   
    RETURN;
END IF;

END IF;

